package dev.veltraph.client.farming.movement.planner;
import dev.veltraph.client.config.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import static dev.veltraph.client.farming.movement.planner.MushroomReferencePlanner.Clearance.*;
class MushroomReferencePlannerTest {
 @Test void creatorRingAndRecoveredStaircaseCannotBeRemapped(){assertFalse(MushroomReferencePlanner.supports(MushroomFarmDesign.RECOVERED));assertFalse(MushroomReferencePlanner.supports(MushroomFarmDesign.RING_CURRENT));assertThrows(IllegalArgumentException.class,()->new MushroomReferencePlanner().start(MushroomFarmDesign.RING_CURRENT,0,0,LaneSide.LEFT));}
 @Test void fixedDiagonalKeysPreserveViewAcrossSupportedSideReversal(){for(float base:new float[]{0,90,180,-90})for(float offset:new float[]{-45,45}){var p=new MushroomReferencePlanner();p.start(MushroomFarmDesign.FARMHELPER_FIXED_45,base,base+offset,LaneSide.LEFT);float yaw=p.yaw();var left=p.keys();assertEquals(offset<0,left.forward());assertEquals(offset>0,left.left());p.observe(BLOCKED,CLEAR,BLOCKED);assertEquals(MushroomReferencePlanner.State.RIGHT,p.state());assertEquals(yaw,p.yaw());assertEquals(offset>0,p.keys().forward());assertEquals(offset<0,p.keys().right());}}
 @Test void rotatingSourceUsesDistinctSignedThirtyAtAllCardinals(){for(float base:new float[]{0,90,180,-90}){var p=new MushroomReferencePlanner();p.start(MushroomFarmDesign.FARMHELPER_ROTATE_30,base,base,LaneSide.LEFT);assertEquals(-30,dev.veltraph.client.farming.movement.Angles.signedDelta(base,p.yaw()),.001);assertTrue(p.keys().forward());p.observe(BLOCKED,CLEAR,BLOCKED);assertEquals(30,dev.veltraph.client.farming.movement.Angles.signedDelta(base,p.yaw()),.001);assertTrue(p.keys().forward());assertEquals(0,p.pitch());}}
 @Test void sdsTransferUsesBackOnlyUntilRealRearWallThenOtherRow(){var p=new MushroomReferencePlanner();p.start(MushroomFarmDesign.FARMHELPER_SDS,0,0,LaneSide.LEFT);p.observe(CLEAR,CLEAR,BLOCKED);assertTrue(p.keys().left());p.observe(CLEAR,CLEAR,CLEAR);assertTrue(p.keys().back());assertFalse(p.keys().left());p.observe(CLEAR,CLEAR,CLEAR);assertTrue(p.keys().back());p.observe(CLEAR,CLEAR,BLOCKED);assertTrue(p.keys().right());assertFalse(p.keys().back());assertEquals(7,p.pitch());}
 @Test void unknownFloorNeverMasqueradesAsSourceWall(){for(var d:new MushroomFarmDesign[]{MushroomFarmDesign.FARMHELPER_FIXED_45,MushroomFarmDesign.FARMHELPER_ROTATE_30,MushroomFarmDesign.FARMHELPER_SDS}){var p=new MushroomReferencePlanner();p.start(d,0,0,LaneSide.LEFT);p.observe(UNKNOWN,CLEAR,BLOCKED);assertEquals(MushroomReferencePlanner.State.PAUSED,p.state());assertFalse(p.keys().forward()||p.keys().left()||p.keys().right()||p.keys().back());p.observe(CLEAR,BLOCKED,BLOCKED);assertEquals(MushroomReferencePlanner.State.LEFT,p.state());}}
 @Test void twoRealWallsPauseWithoutInventingLaneOrRotation(){var p=new MushroomReferencePlanner();p.start(MushroomFarmDesign.FARMHELPER_ROTATE_30,0,0,LaneSide.LEFT);p.observe(BLOCKED,BLOCKED,BLOCKED);assertEquals(MushroomReferencePlanner.State.PAUSED,p.state());assertFalse(p.keys().forward());assertEquals(-30,p.yaw());}
}
